// ============ DISTANCE & TARGETING ============
function getDistance(from, to){
  if(!from.alive||!to.alive) return 999;
  const n=G.players.length;
  let dist=Math.min(Math.abs(from.idx-to.idx), n-Math.abs(from.idx-to.idx));
  // +1马 on target increases distance
  if(to.equips.some(e=>e.equipType==='horse_plus')) dist+=1;
  // -1马 on attacker decreases distance
  if(from.equips.some(e=>e.equipType==='horse_minus')) dist-=1;
  return Math.max(1,dist);
}

function getAttackRange(player){
  const weapon=player.equips.find(e=>e.equipType==='weapon');
  return weapon?weapon.range:1;
}

function canTargetSha(from, to){
  if(!to.alive||from.idx===to.idx) return false;
  // 空城
  if(to.hero.id==='zhugeliang'&&to.hand.length===0) return false;
  return getDistance(from,to)<=getAttackRange(from);
}

function canTargetShunqian(from, to){
  if(!to.alive||from.idx===to.idx) return false;
  return getDistance(from,to)<=1;
}

// ============ DAMAGE & HEAL ============
function dealDamage(target, amount, source){
  target.hp-=amount;
  showDamageFlash();
  addLog(`<span class="log-name">${target.hero.name}</span> 受到 ${amount} 点伤害（剩余${Math.max(0,target.hp)}血）`);

  // 曹操奸雄
  if(target.hero.id==='caocao'&&source){
    // 获得造成伤害的牌（简化：摸1张）
    drawCard(target);
    addLog(`<span class="log-name">${target.hero.name}</span> 发动【奸雄】，摸1张牌`);
  }

  if(target.hp<=0){
    // 濒死求桃
    const taoIdx=target.hand.findIndex(c=>c.type==='tao');
    if(taoIdx>=0){
      discardCard(target, target.hand[taoIdx].id);
      target.hp=1;
      addLog(`<span class="log-name">${target.hero.name}</span> 使用【桃】自救！`);
    } else {
      // 请求其他玩家出桃（AI自动判断）
      let saved=false;
      for(const p of G.players){
        if(p.alive&&p.idx!==target.idx){
          const ti=p.hand.findIndex(c=>c.type==='tao');
          if(ti>=0&&shouldSaveAlly(p,target)){
            discardCard(p, p.hand[ti].id);
            target.hp=1;
            addLog(`<span class="log-name">${p.hero.name}</span> 对 ${target.hero.name} 使用【桃】`);
            saved=true;
            break;
          }
        }
      }
      if(!saved){
        target.alive=false;
        addLog(`<span class="log-name">${target.hero.name}</span>（${target.role.name}）阵亡！`);
        // 弃置所有牌
        target.hand.forEach(c=>G.discard.push(c));
        target.equips.forEach(c=>G.discard.push(c));
        target.hand=[];target.equips=[];
        checkGameOver();
      }
    }
  }
  render();
}

function shouldSaveAlly(saver, target){
  if(saver.role.id==='zhu'||saver.role.id==='zhong'){
    return target.role.id==='zhu'||target.role.id==='zhong';
  }
  if(saver.role.id==='fan'){
    return false; // 反贼不救人
  }
  if(saver.role.id==='nei'){
    // 内奸：主公快死时救
    return target.role.id==='zhu';
  }
  return false;
}

function healPlayer(target, amount){
  target.hp=Math.min(target.maxHp, target.hp+amount);
  addLog(`<span class="log-name">${target.hero.name}</span> 回复 ${amount} 点体力（当前${target.hp}血）`);
}

function showDamageFlash(){
  const el=document.getElementById('damage-flash');
  el.classList.add('show');
  setTimeout(()=>el.classList.remove('show'),300);
}

// ============ CARD EFFECTS ============
function playCard(player, card, target){
  discardCard(player, card.id);
  showPlayedCard(card);

  switch(card.type){
    case 'sha': resolveSha(player, target, card); break;
    case 'tao': resolveTao(player); break;
    case 'juedou': resolveJuedou(player, target); break;
    case 'nanman': resolveNanman(player); break;
    case 'wanjian': resolveWanjian(player); break;
    case 'wuzhong': resolveWuzhong(player); break;
    case 'guohe': resolveGuohe(player, target); break;
    case 'shunqian': resolveShunqian(player, target); break;
    case 'taoyuan': resolveTaoyuan(player); break;
    case 'lebusishu': resolveLebusishu(player, target); break;
    case 'zhuge': case 'qinglong': case 'bagua': case 'jia1': case 'jia1m':
      resolveEquip(player, card); break;
  }
}

function resolveSha(attacker, target, card){
  addLog(`<span class="log-name">${attacker.hero.name}</span> 对 <span class="log-name">${target.hero.name}</span> 使用了【杀】`);
  G.shaUsed=true;

  // 吕布无双：需要2张闪
  const needShan = attacker.hero.id==='lvbu'?2:1;

  // 八卦阵判定
  if(target.equips.some(e=>e.equipType==='armor'&&e.type==='bagua')){
    const judge=Math.random()>0.5;
