// ============ TURN SYSTEM ============
function startTurn(){
  if(G.gameOver) return;
  const player=G.players[G.currentIdx];
  if(!player.alive){nextTurn();return;}

  G.shaUsed=false;
  G.selectedCard=null;
  G.selectedTarget=null;

  // 乐不思蜀判定
  if(player.lebusishu){
    player.lebusishu=false;
    const judge=Math.random()>0.5;
    addLog(`<span class="log-name">${player.hero.name}</span> 的【乐不思蜀】判定：${judge?'生效！跳过出牌阶段':'未生效'}`);
    if(judge){
      setPhase('判定','乐不思蜀生效');
      render();
      setTimeout(()=>{
        setPhase('弃牌','');
        aiDiscardPhase(player);
        setTimeout(()=>nextTurn(),800);
      },1000);
      return;
    }
  }

  // 诸葛亮观星
  if(player.hero.id==='zhugeliang'&&!player.isHuman){
    aiGuangxing(player);
  }

  setPhase('摸牌','');
  drawCard(player, 2);
  addLog(`<span class="log-name">${player.hero.name}</span> 摸了2张牌`);
  render();

  setTimeout(()=>{
    if(player.isHuman){
      setPhase('出牌','请选择手牌使用');
      render();
    } else {
      setPhase('出牌','');
      aiPlayPhase(player);
    }
  }, 600);
}

function endPlayPhase(){
  const player=G.players[G.currentIdx];
  setPhase('弃牌','');
  if(player.isHuman){
    // 检查是否需要弃牌
    if(player.hand.length>player.hp){
      addLog('手牌超过体力值，请弃牌至体力值张数');
      render();
    } else {
      nextTurn();
    }
  } else {
    aiDiscardPhase(player);
    setTimeout(()=>nextTurn(),800);
  }
}

function nextTurn(){
  if(G.gameOver) return;
  G.currentIdx=(G.currentIdx+1)%G.players.length;
  startTurn();
}

function setPhase(phase, detail){
  G.phase=phase;
  document.getElementById('phase-info').textContent=detail||phase;
  document.getElementById('turn-info').textContent=
    `当前回合：${G.players[G.currentIdx].hero.name}（${G.players[G.currentIdx].role.name}）`;
}

// ============ AI LOGIC ============
function aiPlayPhase(player){
  if(G.gameOver||!player.alive) return;

  const role=player.role.id;
  let acted=true;

  while(acted){
    acted=false;
    if(G.gameOver) break;

    // 赵云龙胆：闪当杀
    if(player.hero.id==='zhaoyun'){
      const shanIdx=player.hand.findIndex(c=>c.type==='shan');
      if(shanIdx>=0&&!G.shaUsed||player.hero.id==='zhaoyun'){
        const target=aiChooseTarget(player,'sha');
        if(target){
          const card=player.hand[shanIdx];
          addLog(`<span class="log-name">${player.hero.name}</span> 发动【龙胆】，将【闪】当【杀】使用`);
          playCard(player, card, target);
          acted=true;
          continue;
        }
      }
    }

    // 关羽武圣：红色牌当杀
    if(player.hero.id==='guanyu'&&!G.shaUsed){
      const redIdx=player.hand.findIndex(c=>isRed(c)&&c.type!=='tao');
      if(redIdx>=0){
        const target=aiChooseTarget(player,'sha');
        if(target){
          const card=player.hand[redIdx];
          addLog(`<span class="log-name">${player.hero.name}</span> 发动【武圣】，将红色牌当【杀】使用`);
          playCard(player, card, target);
          acted=true;
          continue;
        }
      }
    }

    // 使用桃
    if(player.hp<player.maxHp){
      const taoIdx=player.hand.findIndex(c=>c.type==='tao');
      if(taoIdx>=0){
        playCard(player, player.hand[taoIdx], null);
        acted=true;
        continue;
      }
    }

    // 装备
    for(let i=0;i<player.hand.length;i++){
      const c=player.hand[i];
      if(CARD_TYPES[c.type]&&CARD_TYPES[c.type].category==='equip'){
        playCard(player, c, null);
        acted=true;
        break;
      }
    }
    if(acted) continue;

    // 杀
    if(!G.shaUsed||player.hero.id==='zhangfei'){
      const shaIdx=player.hand.findIndex(c=>c.type==='sha');
      if(shaIdx>=0){
        const target=aiChooseTarget(player,'sha');
        if(target){
          playCard(player, player.hand[shaIdx], target);
          acted=true;
          continue;
        }
      }
    }

    // 锦囊牌
    const tricks=['wuzhong','guohe','shunqian','juedou','nanman','wanjian','taoyuan','lebusishu'];
    for(const t of tricks){
      const idx=player.hand.findIndex(c=>c.type===t);
      if(idx<0) continue;
      const card=player.hand[idx];

      if(t==='wuzhong'){
        playCard(player, card, null);
        acted=true; break;
      }
      if(t==='nanman'||t==='wanjian'||t==='taoyuan'){
        playCard(player, card, null);
        acted=true; break;
      }
      if(t==='guohe'){
        const target=aiChooseTarget(player,'guohe');
        if(target){playCard(player, card, target);acted=true;break;}
      }
      if(t==='shunqian'){
        const target=aiChooseTarget(player,'shunqian');
        if(target){playCard(player, card, target);acted=true;break;}
      }
      if(t==='juedou'){
        const target=aiChooseTarget(player,'juedou');
        if(target){playCard(player, card, target);acted=true;break;}
      }
      if(t==='lebusishu'){
        const target=aiChooseTarget(player,'lebusishu');
        if(target){playCard(player, card, target);acted=true;break;}
      }
    }
    if(acted) continue;

    // 孙权制衡
    if(player.hero.id==='sunquan'&&player.hand.length>=3){
      const count=Math.min(player.hand.length, Math.floor(Math.random()*3)+1);
      for(let i=0;i<count;i++){
        if(player.hand.length>0){
          const ri=Math.floor(Math.random()*player.hand.length);
          discardCard(player, player.hand[ri].id);
        }
      }
      drawCard(player, count);
      addLog(`<span class="log-name">${player.hero.name}</span> 发动【制衡】，弃${count}张摸${count}张`);
      acted=true;
    }
  }

  setTimeout(()=>endPlayPhase(), 500);
}

function aiChooseTarget(player, cardType){
  const enemies=[], allies=[];
  const role=player.role.id;

  G.players.forEach(p=>{
    if(p.idx===player.idx||!p.alive) return;
    // 空城判定
    if(p.hero.id==='zhugeliang'&&p.hand.length===0&&(cardType==='sha'||cardType==='juedou')) return;

    if(role==='zhu'||role==='zhong'){
      if(p.role.id==='fan'||p.role.id==='nei') enemies.push(p);
      else allies.push(p);
    } else if(role==='fan'){
      if(p.role.id==='zhu'||p.role.id==='zhong') enemies.push(p);
      else allies.push(p);
    } else if(role==='nei'){
      // 内奸：先杀反贼，再杀忠臣，最后杀主公
      enemies.push(p);
    }
  });

  // 内奸优先级
  if(role==='nei'){
    enemies.sort((a,b)=>{
      const order={fan:0,zhong:1,zhu:2,nei:3};
      return (order[a.role.id]||0)-(order[b.role.id]||0);
    });
  }

  if(cardType==='sha'){
    const valid=enemies.filter(e=>canTargetSha(player,e));
    if(valid.length>0) return valid[Math.floor(Math.random()*valid.length)];
    return null;
  }
  if(cardType==='guohe'||cardType==='shunqian'){
    const valid=enemies.filter(e=>getDistance(player,e)<=1);
    if(valid.length>0) return valid[Math.floor(Math.random()*valid.length)];
    return null;
  }
  if(cardType==='juedou'){
    if(enemies.length>0) return enemies[Math.floor(Math.random()*enemies.length)];
    return null;
  }
  if(cardType==='lebusishu'){
    if(enemies.length>0) return enemies[Math.floor(Math.random()*enemies.length)];
    return null;
  }
  return null;
}

function aiDiscardPhase(player){
  while(player.hand.length>player.hp&&player.hand.length>0){
    // 优先弃无用牌
    let discardIdx=-1;
    // 弃闪（赵云除外）
    if(player.hero.id!=='zhaoyun'){
      discardIdx=player.hand.findIndex(c=>c.type==='shan');
    }
    if(discardIdx<0) discardIdx=player.hand.findIndex(c=>c.type==='tao'&&player.hp===player.maxHp);
    if(discardIdx<0) discardIdx=0;
    discardCard(player, player.hand[discardIdx].id);
  }
  render();
}

function aiGuangxing(player){
  // 简化观星：摸牌前看牌堆顶，把好牌放上面
  if(G.deck.length>=2){
    addLog(`<span class="log-name">${player.hero.name}</span> 发动【观星】`);
  }
}

// ============ GAME OVER ============
function checkGameOver(){
  const zhu=G.players.find(p=>p.role.id==='zhu');
  const fans=G.players.filter(p=>p.role.id==='fan'&&p.alive);
  const neis=G.players.filter(p=>p.role.id==='nei'&&p.alive);
  const zhongs=G.players.filter(p=>p.role.id==='zhong'&&p.alive);

  if(!zhu.alive){
    // 主公死亡
    if(neis.length===1&&!fans.some(f=>f.alive)&&!zhongs.some(z=>z.alive)){
      endGame('nei');
    } else {
      endGame('fan');
    }
  } else if(!fans.some(f=>f.alive)&&!neis.some(n=>n.alive)){
    endGame('zhu');
  }
}

function endGame(winner){
  G.gameOver=true;
  const el=document.getElementById('game-over');
  const text=document.getElementById('game-over-text');
  el.classList.add('show');

  if(winner==='zhu'){
    text.className='result-win';
    text.textContent='主公胜利！';
  } else if(winner==='fan'){
    text.className='result-lose';
    text.textContent='反贼胜利！主公阵亡...';
  } else {
    text.className='result-lose';
    text.textContent='内奸胜利！';
  }
}

