  // 检查是否可用
  if(card.type==='sha'&&G.shaUsed&&player.hero.id!=='zhangfei') return;
  if(card.type==='shan') return; // 闪不能主动用
  if(card.type==='tao'&&player.hp>=player.maxHp) return;

  G.selectedCard=cardId;
  G.selectedTarget=null;
  render();

  // 无目标牌直接使用
  const info=CARD_TYPES[card.type];
  if(info.category==='equip'||card.type==='wuzhong'||card.type==='tao'||
     card.type==='nanman'||card.type==='wanjian'||card.type==='taoyuan'){
    // 等待确认
  }
}

function onEnemyClick(targetIdx){
  if(G.gameOver) return;
  const player=G.players[0];
  if(!player.isHuman||G.currentIdx!==0||G.phase!=='出牌') return;
  if(!G.selectedCard) return;

  const card=player.hand.find(c=>c.id===G.selectedCard);
  if(!card) return;

  const target=G.players[targetIdx];
  if(!target.alive) return;

  // 验证目标合法性
  if(card.type==='sha'){
    if(!canTargetSha(player,target)) return;
  } else if(card.type==='guohe'||card.type==='shunqian'){
    if(getDistance(player,target)>1) return;
  } else if(card.type==='juedou'){
    if(target.hero.id==='zhugeliang'&&target.hand.length===0) return;
  } else if(card.type==='lebusishu'){
    // 任何存活非自己
  } else {
    return; // 不需要目标的牌不能点敌人
  }

  G.selectedTarget=targetIdx;
  // 直接执行
  playCard(player, card, target);
  G.selectedCard=null;
  G.selectedTarget=null;
}

function onPlayCard(){
  const player=G.players[0];
  if(!G.selectedCard) return;
  const card=player.hand.find(c=>c.id===G.selectedCard);
  if(!card) return;

  const info=CARD_TYPES[card.type];
  // 无目标牌
  if(['wuzhong','tao','nanman','wanjian','taoyuan'].includes(card.type)){
    playCard(player, card, null);
    G.selectedCard=null;
    return;
  }
  if(info.category==='equip'){
    playCard(player, card, null);
    G.selectedCard=null;
    return;
  }
}

function onEndPlay(){
  if(G.phase!=='出牌'||G.currentIdx!==0) return;
  G.selectedCard=null;
  G.selectedTarget=null;
  endPlayPhase();
}

