  const player=G.players[0];
  if(G.phase!=='弃牌'||G.currentIdx!==0) return;
  if(player.hand.length<=player.hp) return;
  discardCard(player, cardId);
  addLog(`你弃置了一张牌`);
  if(player.hand.length<=player.hp){
    nextTurn();
  } else {
    render();
  }
}

