        if(valid) div.style.borderColor='#ffd700';
      }
    }
    el.appendChild(div);
  });
}

function renderHpDots(player){
  let html='';
  for(let i=0;i<player.maxHp;i++){
    html+=`<span class="hp-dot ${i<player.hp?'full':'empty'}"></span>`;
  }
  return html;
}

function renderPlayer(){
  const p=G.players[0];
  const el=document.getElementById('player-info');
  el.innerHTML=`
    <div class="p-name">${p.hero.name}（${p.role.name}）</div>
    <div class="p-hp">${renderHpDots(p)}</div>
    <div class="p-skill">${p.hero.skill}：${p.hero.skillDesc}</div>
  `;
