function renderHand(){
  const el=document.getElementById('hand-area');
  el.innerHTML='';
  const player=G.players[0];
  const isMyTurn=G.currentIdx===0;
  const isPlayPhase=isMyTurn&&G.phase==='出牌';
  const isDiscardPhase=isMyTurn&&G.phase==='弃牌';

  player.hand.forEach(card=>{
    const info=CARD_TYPES[card.type];
    const div=document.createElement('div');
    let cls='hand-card';
    if(G.selectedCard===card.id) cls+=' selected';

    // 判断是否可用
    let disabled=false;
    if(isPlayPhase){
      if(card.type==='shan') disabled=true;
      if(card.type==='sha'&&G.shaUsed&&player.hero.id!=='zhangfei') disabled=true;
      if(card.type==='tao'&&player.hp>=player.maxHp) disabled=true;
    } else if(!isDiscardPhase){
      disabled=true;
    }
    if(disabled) cls+=' disabled';

    div.className=cls;
    const suitColor=SUIT_COLORS[card.suit]||'#fff';
    div.innerHTML=`
