function drawCard(playerIdx, count) {
  let cards = [];
  for (let i = 0; i < count; i++) {
    if (G.deck.length === 0) {
      // 洗入弃牌堆
      G.deck = [...G.discard];
      G.discard = [];
      for (let j = G.deck.length - 1; j > 0; j--) {
        let k = Math.floor(Math.random() * (j + 1));
        [G.deck[j], G.deck[k]] = [G.deck[k], G.deck[j]];
      }
      if (G.deck.length === 0) return cards;
    }
    let card = G.deck.pop();
    G.players[playerIdx].hand.push(card);
    cards.push(card);
  }
