  document.getElementById('my-hp').innerHTML = renderHpDots(p.hp, p.hero.hp);
  document.getElementById('my-identity').className = 'my-identity ' + p.identity.css;
  document.getElementById('my-identity').textContent = p.identity.name;
  document.getElementById('my-skill').textContent = `【${p.hero.skill}】${p.hero.desc}`;
}

function renderHand() {
  let p = G.players[G.myIndex];
  let html = '';
  p.hand.forEach((card, idx) => {
    let cardClass = getCardClass(card);
    let suitColor = SUIT_COLORS[card.suit];
    let isSelected = idx === G.selectedCard;
    let isDisabled = G.phase !== 'play' && G.phase !== 'response';
    html += `<div class="card ${cardClass} ${isSelected?'selected':''} ${isDisabled?'disabled':''}" 
      onclick="selectCard(${idx})" title="${card.name}">
      <span class="card-suit suit-${suitColor}">${card.suit}</span>
      <span class="card-num">${card.num}</span>
      <span class="card-name">${card.name}</span>
      <span class="card-type">${card.type==='basic'?'基本':card.type==='trick'?'锦囊':'装备'}</span>
    </div>`;
  });
  document.getElementById('hand').innerHTML = html;
}

function getCardClass(card) {
  if (card.name === '杀') return 'card-sha';
  if (card.name === '闪') return 'card-shan';
  if (card.name === '桃') return 'card-tao';
  if (card.type === 'trick') return 'card-trick';
  return 'card-equip';
}

function renderActions() {
  let isMyTurn = G.currentPlayer === G.myIndex && G.phase === 'play' && !G.gameOver;
  document.getElementById('btn-play').disabled = !isMyTurn || G.selectedCard < 0;
  document.getElementById('btn-end').disabled = !isMyTurn;
  let p = G.players[G.myIndex];
  let canSkill = isMyTurn && p.hero.skillType === 'rende';
  document.getElementById('btn-skill').disabled = !canSkill;
}

function renderPhaseInfo() {
  let p = G.players[G.currentPlayer];
  if (!p || G.gameOver) {
    document.getElementById('phase-info').textContent = '';
    return;
  }
  let phaseNames = { draw:'摸牌阶段', play:'出牌阶段', discard:'弃牌阶段', response:'响应阶段' };
  let text = `${p.hero.name} 的${phaseNames[G.phase] || G.phase}`;
  document.getElementById('phase-info').textContent = text;
}

// ============ 卡牌选择 ============
function selectCard(idx) {
  if (G.phase !== 'play' && G.phase !== 'response') return;
  G.selectedCard = G.selectedCard === idx ? -1 : idx;
  G.selectedTarget = -1;
  renderHand();
  renderActions();
  clearTargetHighlights();
}

function selectTarget(idx) {
  if (idx === G.myIndex) return;
  if (G.phase !== 'play' && G.phase !== 'response') return;
  if (G.selectedCard < 0) return;
  let p = G.players[idx];
  if (p.hp <= 0) return;
  G.selectedTarget = G.selectedTarget === idx ? -1 : idx;
  clearTargetHighlights();
  if (G.selectedTarget >= 0) {
    document.getElementById('opp-' + idx).classList.add('target-highlight');
  }
}

function clearTargetHighlights() {
  document.querySelectorAll('.opponent').forEach(el => el.classList.remove('target-highlight'));
}

