// ============ 出牌逻辑 ============
function playSelectedCard() {
  if (G.selectedCard < 0 || G.phase !== 'play') return;
  let p = G.players[G.myIndex];
  let card = p.hand[G.selectedCard];

  if (card.name === '杀') {
    if (G.selectedTarget < 0) { addLog('请选择一个目标！', 'log-system'); return; }
    if (G.shaUsed >= 1 && p.hero.skillType !== 'paoxiao') { addLog('本回合已使用过杀！', 'log-system'); return; }
    let target = G.players[G.selectedTarget];
    if (target.hp <= 0) return;
    executeSha(G.myIndex, G.selectedTarget, card);
  } else if (card.name === '桃') {
    if (p.hp >= p.hero.hp) { addLog('体力已满！', 'log-system'); return; }
    executeTao(G.myIndex, card);
  } else if (card.name === '决斗') {
    if (G.selectedTarget < 0) { addLog('请选择一个目标！', 'log-system'); return; }
    executeDuel(G.myIndex, G.selectedTarget, card);
  } else if (card.name === '南蛮入侵') {
    executeAOE(G.myIndex, card, '南蛮入侵', 'sha');
  } else if (card.name === '万箭齐发') {
    executeAOE(G.myIndex, card, '万箭齐发', 'shan');
  } else if (card.name === '无中生有') {
    executeDraw2(G.myIndex, card);
  } else if (card.name === '过河拆桥') {
    if (G.selectedTarget < 0) { addLog('请选择一个目标！', 'log-system'); return; }
    executeDismantle(G.myIndex, G.selectedTarget, card);
  } else if (card.name === '顺手牵羊') {
    if (G.selectedTarget < 0) { addLog('请选择一个目标！', 'log-system'); return; }
    executeSteal(G.myIndex, G.selectedTarget, card);
  } else if (card.name === '桃园结义') {
    executePeachGarden(G.myIndex, card);
  } else if (card.name === '借刀杀人') {
    if (G.selectedTarget < 0) { addLog('请选择一个目标！', 'log-system'); return; }
    executeBorrow(G.myIndex, G.selectedTarget, card);
  }
}

function removeCard(playerIdx, cardIdx) {
  let card = G.players[playerIdx].hand.splice(cardIdx, 1)[0];
  G.discard.push(card);
  return card;
}

function removeCardById(playerIdx, cardId) {
  let idx = G.players[playerIdx].hand.findIndex(c => c.id === cardId);
  if (idx >= 0) return removeCard(playerIdx, idx);
  return null;
}

// ============ 卡牌效果 ============
function executeSha(srcIdx, tgtIdx, card) {
  let src = G.players[srcIdx];
  let tgt = G.players[tgtIdx];
  removeCardById(srcIdx, card.id);
  G.shaUsed++;
  addLog(`${src.hero.name} 对 ${tgt.hero.name} 使用了【杀】`, 'log-card');

  // 马超铁骑
  if (src.hero.skillType === 'tieqi') {
    let judgeCard = G.deck.pop();
    G.discard.push(judgeCard);
    let isRed = judgeCard.suit === '♥' || judgeCard.suit === '♦';
    addLog(`${src.hero.name} 发动【铁骑】，判定结果: ${judgeCard.suit}${judgeCard.num}（${isRed?'红色':'黑色'}）`, 'log-card');
    if (isRed) {
      addLog(`${tgt.hero.name} 无法闪避！`, 'log-damage');
      dealDamage(srcIdx, tgtIdx, 1, card);
      afterPlay(srcIdx, card);
      return;
    }
  }

  // 赵云龙胆：杀当闪的被动不在这里，但闪当杀在响应时处理
  // 请求目标出闪
  requestResponse(tgtIdx, 'shan', () => {
    addLog(`${tgt.hero.name} 使用了【闪】`, 'log-card');
    afterPlay(srcIdx, card);
  }, () => {
    addLog(`${tgt.hero.name} 未出闪`, 'log-damage');
    dealDamage(srcIdx, tgtIdx, 1, card);
    afterPlay(srcIdx, card);
  });
}

function executeTao(playerIdx, card) {
  let p = G.players[playerIdx];
  removeCardById(playerIdx, card.id);
  p.hp = Math.min(p.hp + 1, p.hero.hp);
  addLog(`${p.hero.name} 使用了【桃】，回复1点体力(${p.hp}/${p.hero.hp})`, 'log-heal');
  afterPlay(playerIdx, card);
}

function executeDuel(srcIdx, tgtIdx, card) {
  let src = G.players[srcIdx];
  let tgt = G.players[tgtIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 对 ${tgt.hero.name} 使用了【决斗】`, 'log-card');
  doDuel(srcIdx, tgtIdx, card);
}

function doDuel(srcIdx, tgtIdx, origCard) {
  // 目标先出杀
  let tgt = G.players[tgtIdx];
  let src = G.players[srcIdx];
  let shaIdx = tgt.hand.findIndex(c => c.name === '杀');
  // 赵云龙胆：闪当杀
  if (shaIdx < 0) shaIdx = tgt.hand.findIndex(c => c.name === '闪' && tgt.hero.skillType === 'longdan');

  if (shaIdx >= 0) {
    let usedCard = removeCard(tgtIdx, shaIdx);
    addLog(`${tgt.hero.name} 打出了【${usedCard.name}】`, 'log-card');
    // 换方向
    setTimeout(() => doDuel(tgtIdx, srcIdx, origCard), 500);
  } else {
    addLog(`${tgt.hero.name} 未出杀，决斗失败！`, 'log-damage');
    dealDamage(srcIdx, tgtIdx, 1, origCard);
    afterPlay(srcIdx, origCard);
  }
}

function executeAOE(srcIdx, card, cardName, responseType) {
  let src = G.players[srcIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 使用了【${cardName}】`, 'log-card');

  let targets = [];
  for (let i = 0; i < G.players.length; i++) {
    if (i !== srcIdx && G.players[i].hp > 0) targets.push(i);
  }
  processAOE(srcIdx, targets, 0, responseType, card, cardName);
}

function processAOE(srcIdx, targets, idx, responseType, origCard, cardName) {
  if (idx >= targets.length) {
    afterPlay(srcIdx, origCard);
    return;
  }
  let tgtIdx = targets[idx];
  let tgt = G.players[tgtIdx];
  if (tgt.hp <= 0) { processAOE(srcIdx, targets, idx+1, responseType, origCard, cardName); return; }

  let needCard = responseType === 'sha' ? '杀' : '闪';
  // 赵云龙胆
  let altCard = responseType === 'sha' ? '闪' : '杀';

  requestResponse(tgtIdx, responseType, () => {
    addLog(`${tgt.hero.name} 打出了【${needCard}】`, 'log-card');
    setTimeout(() => processAOE(srcIdx, targets, idx+1, responseType, origCard, cardName), 300);
  }, () => {
    addLog(`${tgt.hero.name} 未出【${needCard}】`, 'log-damage');
    dealDamage(srcIdx, tgtIdx, 1, origCard);
    setTimeout(() => processAOE(srcIdx, targets, idx+1, responseType, origCard, cardName), 300);
  });
}

function executeDraw2(playerIdx, card) {
  let p = G.players[playerIdx];
  removeCardById(playerIdx, card.id);
  addLog(`${p.hero.name} 使用了【无中生有】`, 'log-card');
  drawCard(playerIdx, 2);
  addLog(`${p.hero.name} 摸了2张牌`, 'log-card');
  afterPlay(playerIdx, card);
}

function executeDismantle(srcIdx, tgtIdx, card) {
  let src = G.players[srcIdx];
  let tgt = G.players[tgtIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 对 ${tgt.hero.name} 使用了【过河拆桥】`, 'log-card');
  if (tgt.hand.length > 0) {
    let rIdx = Math.floor(Math.random() * tgt.hand.length);
    let removed = removeCard(tgtIdx, rIdx);
    addLog(`${tgt.hero.name} 丢失了一张【${removed.name}】`, 'log-damage');
  } else {
    addLog(`${tgt.hero.name} 没有手牌`, 'log-system');
  }
  afterPlay(srcIdx, card);
}

function executeSteal(srcIdx, tgtIdx, card) {
  let src = G.players[srcIdx];
  let tgt = G.players[tgtIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 对 ${tgt.hero.name} 使用了【顺手牵羊】`, 'log-card');
  if (tgt.hand.length > 0) {
    let rIdx = Math.floor(Math.random() * tgt.hand.length);
    let stolen = tgt.hand.splice(rIdx, 1)[0];
    src.hand.push(stolen);
    addLog(`${src.hero.name} 获得了 ${tgt.hero.name} 的一张牌`, 'log-card');
  } else {
    addLog(`${tgt.hero.name} 没有手牌`, 'log-system');
  }
  afterPlay(srcIdx, card);
}

function executePeachGarden(srcIdx, card) {
  let src = G.players[srcIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 使用了【桃园结义】`, 'log-card');
  for (let i = 0; i < G.players.length; i++) {
    let p = G.players[i];
    if (p.hp > 0 && p.hp < p.hero.hp) {
      p.hp++;
      addLog(`${p.hero.name} 回复1点体力(${p.hp}/${p.hero.hp})`, 'log-heal');
    }
  }
  afterPlay(srcIdx, card);
}

function executeBorrow(srcIdx, tgtIdx, card) {
  let src = G.players[srcIdx];
  let tgt = G.players[tgtIdx];
  removeCardById(srcIdx, card.id);
  addLog(`${src.hero.name} 对 ${tgt.hero.name} 使用了【借刀杀人】`, 'log-card');
  // 简化：目标必须对另一人出杀，否则受到1点伤害
  let hasSha = tgt.hand.some(c => c.name === '杀');
  if (hasSha) {
    // AI: 找一个其他活着的角色出杀
    let otherTargets = [];
    for (let i = 0; i < G.players.length; i++) {
      if (i !== tgtIdx && G.players[i].hp > 0) otherTargets.push(i);
    }
    if (otherTargets.length > 0) {
      let victim = otherTargets[Math.floor(Math.random() * otherTargets.length)];
      let shaCard = tgt.hand.find(c => c.name === '杀');
      addLog(`${tgt.hero.name} 被迫对 ${G.players[victim].hero.name} 使用了【杀】`, 'log-card');
      removeCardById(tgtIdx, shaCard.id);
      // 受害者需要出闪
      requestResponse(victim, 'shan', () => {
        addLog(`${G.players[victim].hero.name} 闪避了`, 'log-card');
        afterPlay(srcIdx, card);
      }, () => {
        addLog(`${G.players[victim].hero.name} 未出闪`, 'log-damage');
        dealDamage(tgtIdx, victim, 1, card);
        afterPlay(srcIdx, card);
      });
      return;
    }
  }
  addLog(`${tgt.hero.name} 无法出杀，受到1点伤害！`, 'log-damage');
  dealDamage(srcIdx, tgtIdx, 1, card);
  afterPlay(srcIdx, card);
}

