// ============ 伤害与死亡 ============
function dealDamage(srcIdx, tgtIdx, amount, sourceCard) {
  let tgt = G.players[tgtIdx];
  tgt.hp -= amount;
  addLog(`${tgt.hero.name} 受到${amount}点伤害(${tgt.hp}/${tgt.hero.hp})`, 'log-damage');

  // 曹操奸雄
  if (tgt.hero.skillType === 'jianxiong' && sourceCard) {
    let newCard = { ...sourceCard, id: Date.now() + Math.random() };
    tgt.hand.push(newCard);
    addLog(`${tgt.hero.name} 发动【奸雄】，获得了【${sourceCard.name}】`, 'log-card');
  }

  if (tgt.hp <= 0) {
    handleDying(tgtIdx);
  }
  renderAll();
}

function handleDying(playerIdx) {
  let p = G.players[playerIdx];
  // 濒死求桃
  let taoIdx = p.hand.findIndex(c => c.name === '桃');
  if (taoIdx >= 0) {
    let tao = removeCard(playerIdx, taoIdx);
    p.hp = 1;
    addLog(`${p.hero.name} 使用【桃】自救！(${p.hp}/${p.hero.hp})`, 'log-heal');
    renderAll();
    return;
  }
  // 请求其他玩家救
  for (let i = 0; i < G.players.length; i++) {
    if (i !== playerIdx && G.players[i].hp > 0) {
      let saviorTao = G.players[i].hand.findIndex(c => c.name === '桃');
      if (saviorTao >= 0) {
        // AI: 有概率救人（忠臣救主公，反贼不救）
        let willSave = aiWillSave(i, playerIdx);
        if (willSave) {
          removeCard(i, saviorTao);
          p.hp = 1;
          addLog(`${G.players[i].hero.name} 对 ${p.hero.name} 使用了【桃】`, 'log-heal');
          renderAll();
          return;
        }
      }
    }
  }
  // 死亡
  playerDeath(playerIdx);
}

function aiWillSave(saviorIdx, dyingIdx) {
  let savior = G.players[saviorIdx];
  let dying = G.players[dyingIdx];
  if (dying.identity.id === 'lord' && savior.identity.id === 'loyal') return true;
  if (dying.identity.id === 'lord' && savior.identity.id === 'spy') return Math.random() > 0.5;
  if (savior.identity.id === 'loyal' && dying.identity.id === 'loyal') return Math.random() > 0.3;
  return Math.random() > 0.7;
}

function playerDeath(playerIdx) {
  let p = G.players[playerIdx];
  p.hp = 0;
  addLog(`${p.hero.name}(${p.identity.name}) 阵亡！`, 'log-system');

  // 奖惩
  let killer = findKiller(playerIdx);
  if (killer >= 0) {
    if (p.identity.id === 'rebel') {
      drawCard(killer, 3);
      addLog(`${G.players[killer].hero.name} 击杀反贼，摸3张牌`, 'log-card');
    } else if (p.identity.id === 'loyal' && G.players[killer].identity.id === 'lord') {
      // 主公杀忠臣，弃所有手牌
      G.players[killer].hand = [];
      addLog(`${G.players[killer].hero.name} 误杀忠臣，弃置所有手牌！`, 'log-damage');
    }
  }

  // 检查胜负
  if (checkWinCondition()) return;
  renderAll();
}

function findKiller(deadIdx) {
  // 简化：返回上一个出牌者
  for (let i = 1; i < G.players.length; i++) {
    let idx = (G.currentPlayer - i + G.players.length) % G.players.length;
    if (G.players[idx].hp > 0) return idx;
  }
  return -1;
}

function checkWinCondition() {
  let lord = G.players.find(p => p.identity.id === 'lord');
  let lordAlive = lord && lord.hp > 0;
  let rebelsAlive = G.players.filter(p => p.identity.id === 'rebel' && p.hp > 0).length;
  let loyalAlive = G.players.filter(p => p.identity.id === 'loyal' && p.hp > 0).length;
  let spy = G.players.find(p => p.identity.id === 'spy');
  let spyAlive = spy && spy.hp > 0;

  if (!lordAlive) {
    if (spyAlive && rebelsAlive === 0 && loyalAlive === 0) {
      endGame('内奸胜利！', '内奸成功存活到最后', '#8e44ad');
    } else {
      endGame('反贼胜利！', '主公已被击败', '#27ae60');
    }
    return true;
  }
  if (rebelsAlive === 0 && (!spyAlive || (loyalAlive > 0))) {
    endGame('主公胜利！', '所有反贼和内奸已被消灭', '#c0392b');
    return true;
  }
  return false;
}

function endGame(title, msg, color) {
  G.gameOver = true;
  document.getElementById('go-title').textContent = title;
  document.getElementById('go-title').style.color = color;
  document.getElementById('go-msg').textContent = msg;
  document.getElementById('game-over').style.display = 'flex';
  renderAll();
}

