// ============ 响应系统 ============
function requestResponse(playerIdx, responseType, onSuccess, onFail) {
  if (playerIdx === G.myIndex) {
    // 玩家手动响应
    G.waitingResponse = { responseType, onSuccess, onFail };
    G.phase = 'response';
    renderAll();
    addLog('请选择一张【' + (responseType==='sha'?'杀':'闪') + '】来响应，或点击"放弃"', 'log-system');
  } else {
    // AI自动响应
    setTimeout(() => {
      let p = G.players[playerIdx];
      let cardIdx = p.hand.findIndex(c => c.name === responseType);
      // 赵云龙胆
      if (cardIdx < 0 && p.hero.skillType === 'longdan') {
        let alt = responseType === 'sha' ? '闪' : '杀';
        cardIdx = p.hand.findIndex(c => c.name === alt);
      }
      if (cardIdx >= 0) {
        let used = removeCard(playerIdx, cardIdx);
        addLog(`${p.hero.name} 使用了【${used.name}】`, 'log-card');
        onSuccess();
      } else {
        onFail();
      }
    }, 600);
  }
}

function respondWithCard() {
  if (!G.waitingResponse || G.selectedCard < 0) return;
  let p = G.players[G.myIndex];
  let card = p.hand[G.selectedCard];
  let resp = G.waitingResponse;
  if (card.name === resp.responseType) {
    removeCardById(G.myIndex, card.id);
    G.waitingResponse.onSuccess();
    G.waitingResponse = null;
    G.phase = 'play';
    G.selectedCard = -1;
    renderAll();
  } else if (p.hero.skillType === 'longdan') {
    let alt = resp.responseType === 'sha' ? '闪' : '杀';
    if (card.name === alt) {
      removeCardById(G.myIndex, card.id);
      G.waitingResponse.onSuccess();
      G.waitingResponse = null;
      G.phase = 'play';
      G.selectedCard = -1;
      renderAll();
    }
  } else {
    addLog('这张牌无法响应！', 'log-system');
  }
}

function respondPass() {
  if (!G.waitingResponse) return;
  G.waitingResponse.onFail();
  G.waitingResponse = null;
  G.phase = 'play';
  G.selectedCard = -1;
  renderAll();
}

// ============ 技能效果 ============
function afterPlay(playerIdx, card) {
  let p = G.players[playerIdx];
  // 黄月英集智
  if (p.hero.skillType === 'jizhi' && card && card.type === 'trick') {
    drawCard(playerIdx, 1);
    addLog(`${p.hero.name} 发动【集智】，摸1张牌`, 'log-card');
  }
  G.selectedCard = -1;
  G.selectedTarget = -1;
  clearTargetHighlights();
  renderAll();
}

function useSkill() {
  let p = G.players[G.myIndex];
  if (p.hero.skillType !== 'rende' || G.phase !== 'play') return;
  if (G.selectedCard < 0) { addLog('请先选择要给出的牌', 'log-system'); return; }
  if (G.selectedTarget < 0) { addLog('请选择一个目标', 'log-system'); return; }
  let card = p.hand[G.selectedCard];
  let tgt = G.players[G.selectedTarget];
  p.hand.splice(G.selectedCard, 1);
  tgt.hand.push(card);
  addLog(`${p.hero.name} 发动【仁德】，将【${card.name}】交给 ${tgt.hero.name}`, 'log-card');
  G.selectedCard = -1;
  G.selectedTarget = -1;
  clearTargetHighlights();
  renderAll();
}

